"""Build a standalone review shell and editable artwork layouts, not a production host."""
from pathlib import Path
import json,base64,mimetypes,re
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'catalogue/dist';REVIEW=ROOT/'catalogue/review';REVIEW.mkdir(exist_ok=True)
pages={}
for p in OUT.rglob('index.html'):
 path='/'+str(p.parent.relative_to(OUT)).strip('.')+'/'
 if path=='//':path='/'
 pages[path]=p.read_text()
assets={}
for p in (OUT/'assets').iterdir():
 if p.suffix in ['.css','.js']:assets['/assets/'+p.name]={'type':p.suffix,'value':p.read_text()}
 elif p.suffix in ['.webp','.jpg','.png','.jpeg']:assets['/assets/'+p.name]={'type':'image','value':'data:'+mimetypes.guess_type(str(p))[0]+';base64,'+base64.b64encode(p.read_bytes()).decode()}
payload=json.dumps({'pages':pages,'assets':assets},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
html='''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Brewtanist · ตรวจเว็บสินค้า</title><style>body{margin:0;background:#f7f4eb;font:14px sans-serif}.ribbon{padding:12px 20px;background:#244737;color:#fff;display:flex;gap:15px;flex-wrap:wrap;align-items:center}.ribbon a{color:#fff}iframe{width:100%;border:0;min-height:850px;display:block}</style></head><body><div class="ribbon"><strong>BREWTANIST · เว็บตรวจงาน</strong><span>ยังไม่ใช่เว็บหลัก · ไม่มีการรับเงินหรือเชื่อมสต็อก</span><a href="#/shop/">ดูสินค้าทั้งหมด</a><a href="https://brewtanist.github.io/" target="_blank" rel="noopener">เว็บไซต์ร้าน ↗</a></div><iframe id="frame" title="ตัวอย่างเว็บไซต์ Brewtanist"></iframe><script type="application/json" id="bundle">__BUNDLE__</script><script>
const B=JSON.parse(document.getElementById('bundle').textContent),frame=document.getElementById('frame');
function show(){let target=location.hash.slice(1)||'/shop/';const query=target.includes('?')?'?'+target.split('?')[1]:'';const path=target.split('?')[0];let html=B.pages[path]||B.pages['/shop/'];
 html=html.replace(/<link rel="stylesheet" href="([^\"]+)">/g,(m,k)=>B.assets[k]?'<style>'+B.assets[k].value+'</style>':m);
 html=html.replace(/<script src="([^\"]+)" defer><\/script>/g,(m,k)=>B.assets[k]?'<script>'+B.assets[k].value.replaceAll('new URLSearchParams(location.search)','new URLSearchParams(window.__REVIEW_QUERY__ || location.search)')+'<\/script>':m);
 html=html.replace(/src="(\/assets\/[^\"]+)"/g,(m,k)=>B.assets[k]?.type==='image'?'src="'+B.assets[k].value+'"':m);
 const bridge='<script>window.__REVIEW_QUERY__='+JSON.stringify(query)+';document.addEventListener("click",e=>{const a=e.target.closest("a");if(!a)return;const h=a.getAttribute("href");if(h&&h.startsWith("/")){e.preventDefault();parent.postMessage({type:"review-route",path:h},"*");}});document.addEventListener("change",e=>{if(e.target.id==="market-category"&&document.querySelectorAll("#market-products .market-card").length<17){e.stopImmediatePropagation();const c=e.target.value;parent.postMessage({type:"review-route",path:c==="all"?"/shop/":"/shop/"+c+"/"},"*");}},true);const height=()=>parent.postMessage({type:"review-height",height:document.documentElement.scrollHeight},"*");window.addEventListener("load",height);new ResizeObserver(height).observe(document.documentElement);<\/script>';
 html=html.replace('</head>',bridge+'</head>');frame.style.height='1000px';frame.srcdoc=html;scrollTo(0,0);}
window.addEventListener('message',e=>{if(e.source!==frame.contentWindow)return;if(e.data?.type==='review-route'&&typeof e.data.path==='string'&&B.pages[e.data.path.split('?')[0]])location.hash=e.data.path;if(e.data?.type==='review-height'&&Number.isFinite(e.data.height))frame.style.height=Math.min(40000,Math.max(850,e.data.height))+'px';});window.addEventListener('hashchange',show);show();
</script></body></html>'''
(REVIEW/'index.html').write_text(html.replace('__BUNDLE__',payload))
products=json.loads((ROOT/'_data/brewtanist/products.json').read_text())['items']
def pic(p):
 b=(ROOT/p['image'].lstrip('/')).read_bytes();return 'data:image/webp;base64,'+base64.b64encode(b).decode()
from html import escape as E
packs=''.join('<div class="pack"><img src="'+pic(p)+'" alt="'+E(p['alt'])+'"><strong>'+E(p['name'])+'</strong><span>'+E(p['notes'])+'</span></div>' for p in products)
art='''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><link href="https://fonts.googleapis.com/css2?family=Bai+Jamjuree:wght@400;500;600;700&family=Lexend:wght@400;500;600&family=MuseoModerno:wght@600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#deded5;color:#244737;font-family:'Bai Jamjuree',sans-serif}.art{position:relative;background:#f6f1e5;overflow:hidden}.wide{width:1920px;height:900px;padding:74px 90px;display:grid;grid-template-columns:.8fr 1.2fr;gap:40px;align-items:center}.brand{font:600 37px 'MuseoModerno',sans-serif}.eyebrow{font:500 14px 'Lexend';letter-spacing:3px;margin:24px 0}.art h1{font-size:83px;line-height:1.16;letter-spacing:-3px;margin:25px 0 30px}.art p{font-size:27px;line-height:1.65;max-width:570px}.cta{display:inline-block;padding:16px 25px;border:1px solid #244737;border-radius:32px;margin-top:24px;font-size:22px}.packs{display:flex;align-items:center;gap:10px;position:relative;z-index:1}.pack{flex:1;text-align:center;min-width:0}.pack img{width:100%;height:470px;object-fit:contain;filter:drop-shadow(0 20px 16px #29433422)}.pack strong{display:block;font:500 23px 'Lexend';margin-top:12px}.pack span{display:block;font:400 13px/1.5 'Lexend';margin:12px 5px}.circle{position:absolute;width:850px;height:850px;border-radius:50%;background:#dce6cc;right:-100px;top:-140px}.square{width:1080px;height:1080px;padding:65px;display:flex;flex-direction:column}.square .circle{width:1000px;height:1000px;right:-300px;top:380px}.square h1{font-size:73px;margin:24px 0}.square p{font-size:23px;margin:0}.square .pack img{height:440px}.square .packs{margin-top:25px}.square .pack strong{font-size:22px}.square .pack span{font-size:12px}.bottom{position:relative;z-index:2;margin-top:auto;display:flex;justify-content:space-between;border-top:1px solid #71836c;padding-top:22px;font-size:21px}.wide .copy{z-index:2}.art .fine{font-size:15px}</style></head><body><section class="art wide" id="wide"><i class="circle"></i><div class="copy"><div class="brand">The Brewtanist</div><div class="eyebrow">HOUSE BLENDS / TAKE HOME</div><h1>เลือกกาแฟ<br>กลับไปชงเอง</h1><p>ชอบช็อกโกแลต วานิลลา<br>หรือกลิ่นผลไม้?<br>ลองดู House Blend ทั้งสามตัว</p><span class="cta">ดูกาแฟในร้าน Shopee ↗</span></div><div class="packs">__PACKS__</div></section><section class="art square" id="square"><i class="circle"></i><div class="brand">The Brewtanist</div><div class="eyebrow">YOUR COFFEE. YOUR WAY.</div><h1>วันนี้อยากชงตัวไหน?</h1><p>House Blend สามตัว สามโทนกลิ่นรส</p><div class="packs">__PACKS__</div><div class="bottom"><span>เลือกกาแฟกลับบ้าน</span><span>shopee.co.th/brewtanist ↗</span></div></section></body></html>'''
(REVIEW/'artwork.html').write_text(art.replace('__PACKS__',packs))
print('Created self-contained product review and two artwork layouts using original packaging renders.')
